import unittest

from solucao import pegar
from solucao import pegar_texto


class TestPegarPelaChave(unittest.TestCase):
    def test_pega_o_valor_da_chave(self):
        """pegar devolve o valor guardado na chave pedida"""
        self.assertEqual(pegar({"a": 10, "b": 20}, "b"), 20)

    def test_pega_outra_chave(self):
        """pegar devolve o valor de outra chave do mesmo dicionario"""
        self.assertEqual(pegar({"a": 10, "b": 20}, "a"), 10)

    def test_pega_o_valor_da_chave_em_texto(self):
        """pegar_texto devolve o valor da chave escrito em texto"""
        self.assertEqual(pegar_texto({"a": 10}, "a"), "10")

    def test_pega_outro_valor_em_texto(self):
        """pegar_texto escreve em texto o valor de cada chamada"""
        self.assertEqual(pegar_texto({"uva": 6}, "uva"), "6")

